        },
        addLabel: function(prId, label) { scmCalls.addLabel.push({ prId: prId, label: label }); },
        resolveThread: function(prId, thread) { scmCalls.resolveThread.push({ prId: prId, thread: thread }); },
        listPrs: function(state) {
