            }
        });
        var result = shared.createGitOps(fakePrHelper())
            .performGitOperations('test/TS-1', 'msg', null, 'testing/');
        assert.equal(result.success, true);
        assert.ok(calls.indexOf('git push -u origin test/TS-1 --force') !== -1);
