        assert.equal(attachments[0].ticketKey, 'TS-82');
        assert.equal(attachments[0].filePath, 'outputs/failed_description_TS-82.md');
        assert.equal(fieldUpdates.length, 1);
        assert.equal(fieldUpdates[0].key, 'TS-82');
    });

