       getTracker().postComment(storyKey, 'h3. ⚠️ Bug Fix Did Not Pass Automated Tests\nThe following Test Cases failed with a product regression:\n' + failureList + '\nThe Bug is being returned to *Ready For Development* for a corrected fix.');
   } catch (e) {
       console.warn('Failed to post bug return comment:', e);
   }

   removeAutomationLabels(storyKey, ???params);
   return { success: true, status: 'failed', storyKey: storyKey, failedTestCases: failedResults.map(...) };
}
