        if (openPr) {
            prNumber = openPr.number;
            prUrl = openPr.html_url;
            prBranch = openPr.head && openPr.head.ref;
        }
    }

    return { prNumber: prNumber, prUrl: prUrl, prBranch: prBranch };
}

