        if (localSha && remoteSha && localSha === remoteSha) return 'identical';
        if (mergeBase && mergeBase === remoteSha && mergeBase !== localSha) return 'ahead';
        if (mergeBase && mergeBase === localSha && mergeBase !== remoteSha) return 'behind';
