        var body = resolveEntryBody(ic, readFile);
        if (!body) return;
        var path = ic.path || ic.file || '(file unknown)';
        var line = ic.line ? ':' + ic.line : '';
        entries += '#' + (idx + 1) + '. *' + path + line + '*\n';
        entries += '{code}' + body + '{code}\n\n';
    });
